    if role=='lic': right=f'<span class="btn o sm">{ic("wallet",15)}<span class="num">R$ 7.000,00</span></span><span class="btn g sm" style="gap:8px"><span style="width:28px;height:28px;border-radius:50%;background:var(--accent-soft);display:inline-flex;align-items:center;justify-content:center;font-weight:700;color:#6B5220">A</span>Ana R.{ic("chevron-down",14)}</span>'
    else: right=f'<span class="btn p sm">{ic("log-in",15)}Entrar</span>'
    return f'<div class="top" style="position:relative"><div class="logo">{logoA(30)}Arremate</div>{nav}{right}</div>'+demo()
