def lcard(L,hover=False,w=None):
    k,l,fmt,price,time,b,s,n=L
    badge=f'<span class="badge {b}">{s}</span>' if s!='Encerrando' else f'<span class="badge b-warn">{ic("timer",12)}Encerrando</span>'
    pl='Arrematado por' if s=='Encerrado' else ('Lance inicial' if s=='Agendado' else 'Lance atual')
    tl='Encerrou' if s=='Encerrado' else ('Abre' if s=='Agendado' else 'Termina em')
    tv='23/10 17:03' if s=='Encerrado' else time.replace('Abre ','')
    bids=f'<span class="row xs muted" style="gap:4px">{ic("gavel",12)}{n} lances</span>' if n else '<span class="xs muted">Sem lances</span>'
    return f'''<div class="card lcard" style="overflow:hidden;{f'width:{w}px;' if w else ''}{'outline:2px solid var(--ring);' if hover else ''}">{pic(k,220)}<div class="meta" style="padding:14px 16px 16px;display:flex;flex-direction:column;gap:6px"><div class="row" style="justify-content:space-between">{badge}<span class="xs muted">Lote {l}</span></div><h3 class="serif clamp2" style="font-size:17px;font-weight:600;line-height:1.25;min-height:42px">{IMG[k][1]}</h3><div class="small muted clamp1">{IMG[k][2]} · {IMG[k][3]}</div><div class="sp"></div><div class="kv"><span>{pl}</span><span class="price" style="font-size:18px">{price}</span></div><div class="kv"><span class="row" style="gap:4px">{ic("clock",13)}{tl}</span><span class="num" style="font-weight:600">{tv}</span></div><div class="row" style="justify-content:space-between;margin-top:4px">{bids}<span class="row" style="gap:6px"><span class="btn o sm">{ic("info",14)}Detalhes</span><span class="btn p sm">Abrir sala</span></span></div></div></div>'''
def vitrine_grid(lots,cols=4,w=None): return f'<div class="grid" style="grid-template-columns:repeat({cols},1fr);gap:20px">{"".join(lcard(x) for x in lots)}</div>'
def vtabs(): return f'<div class="tabs"><span class="on">{ic("radio",14)}Ao vivo <span class="ct">11</span></span><span>{ic("calendar-clock",14)}Agendados <span class="ct">2</span></span><span>{ic("archive",14)}Encerrados <span class="ct">6</span></span></div>'
