    return f'<div class="dialog" style="width:860px;padding:24px">{head}<div style="display:grid;grid-template-columns:340px 1fr;gap:24px;margin-top:14px"><div>{pic(k,340,"border-radius:8px")}<div class="cred" style="margin-top:6px">The Met Open Access · CC0</div></div><div><div class="kv" style="margin-bottom:6px"><span>Lance atual · 9 lances</span><span class="price" style="font-size:26px">R$ 950,00</span></div>{dl}</div></div>{foot}</div>'
