BIDS=[('R$ 950,00','Licitante A•••-47','15:01:12',None),('R$ 900,00','Licitante C•••-12','14:58:40','2 min 32 s'),('R$ 850,00','Licitante A•••-47','14:51:05','7 min 35 s'),('R$ 800,00','Licitante R•••-03','14:30:22','20 min 43 s'),('R$ 750,00','Licitante C•••-12','14:12:00','18 min 22 s')]
def bidlist(rows=BIDS):
    out=''
    for i,(v,w,t,gap) in enumerate(rows):
        if gap: out+=f'<div class="xs muted row" style="gap:6px;padding:2px 0 2px 10px;border-left:2px dashed var(--border);margin-left:6px">{ic("hourglass",11)}+{gap}</div>'
        out+=f'<div class="row" style="justify-content:space-between;padding:6px 0"><span class="row small" style="gap:8px">{ic("gavel",14) if i==0 else ic("user",14)}<span>{w}{" <span class=\"badge b-ok\" style=\"padding:1px 6px\">líder</span>" if i==0 else ""}</span></span><span class="row" style="gap:10px"><span class="xs muted num">{t}</span><b class="num" style="white-space:nowrap">{v}</b></span></div>'
    return out
