def confirm(state='ok',w=440):
    btn={'ok':f'<span class="btn p">{ic("gavel",15)}Confirmar lance</span>','load':f'<span class="btn p">{ic("loader-circle",15)}Enviando…</span>'}.get(state,'')
    top=f'<div class="row" style="gap:12px;align-items:flex-start">{thumb("inro",64)}<div style="min-width:0"><h3 class="serif clamp2" style="font-size:17px;font-weight:600;line-height:1.25">{IMG["inro"][1]}</h3><div class="xs muted">Lote 0006 · Yamada Jōkasai</div></div></div>'
    val=f'<div style="text-align:center;padding:16px;margin:14px 0 8px;background:var(--muted);border-radius:var(--r-md)"><div class="small muted">Seu lance</div><div class="price" style="font-size:38px;color:var(--primary)">R$ 1.000,00</div><div class="xs muted">Fica comprometido da carteira enquanto você liderar</div></div>'
    sim=f'<div class="row xs" style="gap:6px;color:var(--warn);justify-content:center;margin-bottom:14px">{ic("flask-conical",13)}Valor simulado · nenhuma cobrança real</div>'
    if state=='err': mid='<div style="height:14px"></div>'+alert('err','circle-alert','O lance mínimo mudou.','Outro licitante cobriu. Novo mínimo: R$ 1.050,00.')+f'<div class="row" style="justify-content:flex-end;gap:8px;margin-top:14px"><span class="btn g">Cancelar</span><span class="btn p">Revisar lance R$ 1.050,00</span></div>'
    elif state=='succ': mid='<div style="height:14px"></div>'+alert('ok','circle-check','Lance aceito. Você está liderando.','R$ 1.000,00 comprometido · 15:03:41 BRT')+f'<div class="row" style="justify-content:flex-end;margin-top:14px"><span class="btn p">Fechar</span></div>'
    else: mid=f'{val}{sim}<div class="row" style="justify-content:flex-end;gap:8px"><span class="btn g">Cancelar</span>{btn}</div>'
    title='<h2 class="serif" style="font-size:20px;margin-bottom:12px">Confirmar lance</h2>'
    return f'<div class="dialog" style="width:{w}px">{title}{top}{mid if state in ("err","succ") else ""}{"" if state in ("err","succ") else mid}</div>'
