steps=lambda cols: f'<div class="grid" style="grid-template-columns:repeat({cols},1fr);gap:16px">'+''.join(f'<div class="card" style="padding:18px"><span style="width:40px;height:40px;border-radius:10px;background:var(--accent-soft);display:inline-flex;align-items:center;justify-content:center;color:#6B5220">{ic(i,20)}</span><h3 class="serif" style="font-size:17px;margin-top:10px">{t}</h3><p class="small muted" style="margin-top:4px">{d}</p></div>' for i,t,d in STEPS)+'</div>'
rules=f'<div class="card" style="padding:20px"><h3 class="serif" style="font-size:18px;margin-bottom:8px">{ic("scale",17)} Regras essenciais</h3>'+''.join(f'<div class="kv" style="padding:7px 0;border-bottom:1px solid var(--border)"><span>{a}</span><span>{b}</span></div>' for a,b in [('Moeda','Real (BRL), simulado'),('Depósito','R$ 1 a R$ 100.000 por vez'),('Ordem da vitrine','Termina antes primeiro'),('Horário','Brasília (UTC−3)'),('Empate','Vale o primeiro lance aceito pelo servidor')])+'</div>'
cdesk2=f'<div class="frame" style="width:1440px">{hdr3("Como funciona")}<div style="padding:40px"><h1 class="serif" style="font-size:38px;font-weight:600">Como funciona o Arremate</h1><p class="muted" style="max-width:720px;margin:6px 0 24px">Uma casa de leilão de demonstração: lances em tempo real, saldo simulado e auditoria pública de cada lance.</p>{steps(5)}<div style="display:grid;grid-template-columns:1fr 1fr;gap:24px;margin-top:24px">{rules}<div class="card" style="padding:20px;display:flex;flex-direction:column;justify-content:space-between"><div><h3 class="serif" style="font-size:18px">Pronto para participar?</h3><p class="small muted" style="margin-top:4px">Crie a conta e ganhe acesso aos lotes ao vivo.</p></div><div class="row" style="gap:8px;margin-top:14px"><span class="btn p">{ic("user-plus",15)}Criar conta</span><span class="btn o">{ic("gavel",15)}Ver leilões</span></div></div></div></div>{foot2()}</div>'
body=f'''<div class="board">{bh('R10 · Como funciona','Página estática com Card existentes. Estados não se aplicam. Conteúdo reflete D04–D06.')}<div class="flabel"><b>R10.1</b>Desktop 1440</div>{cdesk2}
<div style="margin-top:28px">{mob('R10.2','Mobile',f'{mhdr("Como funciona",True)}<div style="padding:16px"><h1 class="serif" style="font-size:26px;font-weight:600;margin-bottom:12px">Como funciona</h1>{steps(1)}<div style="height:16px"></div>{rules}<span class="btn p lg" style="width:100%;margin-top:16px">{ic("user-plus",16)}Criar conta</span></div>{foot2(True)}')}</div></div>'''
sv('R10-como-funciona',P3('R10',body))
print('ok')
